#[derive(Clone)]
struct Address { city: String }
#[derive(Clone)]
struct Person { name: String, home: Address }

let moved = Person {
    home: Address { city: "Berlin".into(), ..p.home },
    ..p.clone()          // `..p` alone would partially move p
};

